<script>
(function(window,document){
  var attempts=0;
  function initScheduledCareSelects(){
    var $=window.jQuery;
    if(!$||!$.fn||!$.fn.select2){
      if(attempts++<40)window.setTimeout(initScheduledCareSelects,100);
      return;
    }
    $('.js-sc-remote').each(function(){
      var select=$(this);
      if(select.hasClass('select2-hidden-accessible'))return;
      select.select2({
        theme:'bootstrap4',width:'100%',allowClear:true,minimumInputLength:0,placeholder:select.data('placeholder'),dropdownCssClass:'sc-select2-dropdown',
        ajax:{
          url:@json(route('v3.scheduled-care.catalog')),dataType:'json',delay:300,cache:true,
          data:function(params){return{tipo:select.data('catalog'),q:params.term||'',page:params.page||1};},
          processResults:function(data){return{results:data.results||[],pagination:data.pagination||{more:false}};}
        },
        language:{
          searching:function(){return'Buscando…';},
          noResults:function(){return'No se encontraron resultados';},
          errorLoading:function(){return'No se pudo cargar la búsqueda';}
        }
      });
    });
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initScheduledCareSelects);
  else initScheduledCareSelects();
})(window,document);
</script>
